829	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
830	     * value is deterministic in the customer code and is the standard Luhn check digit: each
831	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
832	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
833	     * brings the weighted sum up to the next multiple of ten.
834	     *
835	     * @param customerCode the owner's customer code, possibly {@code null}
836	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
837	     */
838	    public static Integer checkDigit(String customerCode) {
839	        if (customerCode == null) {
840	            return null;
841	        }
842	        int sum = 0;
843	        boolean dbl = true;
844	        for (int i = customerCode.length() - 1; i >= 0; i--) {
845	            char c = customerCode.charAt(i);
846	            if (c < '0' || c > '9') {
847	                continue;
848	            }
849	            int d = c - '0';
850	            if (dbl) {
851	                d *= 2;
852	                if (d > 9) {
853	                    d -= 9;
854	                }
855	            }
856	            sum += d;
857	            dbl = !dbl;
858	        }
859	        return (10 - (sum % 10)) % 10;
860	    }
